/*
* @dev This function is used to add new connectors to a vault
* @param vaultId The id of the vault
* @param _connectorAddresses An array of connector addresses
*/
function addConnector(uint256 vaultId, address[] calldata _connectorAddresses, bool[] calldata _enableds)
    external
    onlyVaultMaintainer(vaultId)
    vaultExists(vaultId)
{
    Vault storage vault = vaults[vaultId];
    for (uint256 i = 0; i < _connectorAddresses.length; i++) {
        vault.connectors[_connectorAddresses[i]].enabled = _enableds[i];
        emit ConnectorAdded(vaultId, _connectorAddresses[i]);
    }
}

/*
* @dev This function is used to add or remove new trusted tokens to an specific connector
* @param vaultId The id of the vault
* @param _connectorAddress The address of the connector
* @param _tokens An array of token addresses
* @param _trusteds An array of booleans indicating if the token is trusted or not
*/
function updateConnectorTrustedTokens(
    uint256 vaultId,
    address _connectorAddress,
    address[] calldata _tokens,
    bool trusted
) external onlyVaultMaintainer(vaultId) vaultExists(vaultId) {
    Vault storage vault = vaults[vaultId];
    for (uint256 i = 0; i < _tokens.length; i++) {
        vault.connectors[_connectorAddress].trustedTokens[_tokens[i]] = trusted;
    }
    emit ConnectorTrustedTokensUpdated(vaultId, _connectorAddress, _tokens, trusted);
}

// @dev This function is used to remove trusted positions from a vault
function removeTrustedPosition(uint256 vaultId, bytes32 _positionId)
    external
    onlyVaultMaintainer(vaultId)
    vaultExists(vaultId)
{
    Vault storage vault = vaults[vaultId];
    if (!vault.trustedPositionsBP[_positionId].isEnabled) revert NotExist();
    uint256 length = vault.holdingPositions.length;
    for (uint256 i = 0; i < length; i++) {
        if (vault.holdingPositions[i].positionId == _positionId) {
            revert CannotRemovePosition(vaultId, _positionId);
        }
    }
    emit TrustedPositionRemoved(vaultId, _positionId);
    delete vault.trustedPositionsBP[_positionId];
}

function executeWithdraw(uint256 maxIterations) public onlyManager nonReentrant whenNotPaused {
    if (currentWithdrawGroup.isFullfilled == false) {
        revert NoyaAccounting_ThereIsAnActiveWithdrawGroup();
    }
    uint64 i = 0;
    uint256 firstTemp = withdrawQueue.first;

    uint256 withdrawFeeAmount = 0;
    uint256 processedBaseTokenAmount = 0;
    // loop through the withdraw queue and execute the withdraws
    while (
        currentWithdrawGroup.lastId > firstTemp
            && withdrawQueue.queue[firstTemp].calculationTime + withdrawWaitingTime <= block.timestamp
            && i < maxIterations
    ) {
        i += 1;
        WithdrawRequest memory data = withdrawQueue.queue[firstTemp];
        uint256 shares = data.shares;
        // calculate the base token amount that the user will receive based on the total available amount
        uint256 baseTokenAmount =
            data.amount * currentWithdrawGroup.totalABAmount / currentWithdrawGroup.totalCBAmountFullfilled;

        withdrawRequestsByAddress[data.owner] -= shares;
        _burn(data.owner, shares);

        processedBaseTokenAmount += data.amount;
        {
            uint256 feeAmount = baseTokenAmount * withdrawFee / FEE_PRECISION;
            withdrawFeeAmount += feeAmount;
            baseTokenAmount = baseTokenAmount - feeAmount;
        }

        baseToken.safeTransfer(data.receiver, baseTokenAmount);
        emit ExecuteWithdraw(
            firstTemp, data.owner, data.receiver, shares, data.amount, baseTokenAmount, block.timestamp
        );
        delete withdrawQueue.queue[firstTemp];
        // increment the first index of the withdraw queue
        firstTemp += 1;
    }
    totalWithdrawnAmount += processedBaseTokenAmount;

    if (withdrawFeeAmount > 0) {
        baseToken.safeTransfer(withdrawFeeReceiver, withdrawFeeAmount);
    }
    withdrawQueue.first = firstTemp;
    // if the withdraw group is fullfilled and there are no withdraws that are waiting for execution, we delete the withdraw group
    if (currentWithdrawGroup.lastId == firstTemp) {
        delete currentWithdrawGroup;
    }
}

function withdrawFromStargatePool(StargateRequest calldata withdrawRequest) external onlyManager nonReentrant {
    address lpAddress = LPStaking.poolInfo(withdrawRequest.poolId).lpToken;
    address underlyingToken = IStargatePool(lpAddress).token();
    if (withdrawRequest.LPStakingAmount > 0) {
        IStargateLPStaking(LPStaking).withdraw(withdrawRequest.poolId, withdrawRequest.LPStakingAmount);
    }
    if (withdrawRequest.routerAmount > 0) {
        stargateRouter.instantRedeemLocal(
